const lesson = (code, title, goal, storyBeat, steps, mistake, remember, visual, prompt, options, answer, explain) => ({
  id: code.toLowerCase().replaceAll(' ', '-'), kind: 'lesson', code, title, goal, storyBeat,
  steps, mistake, remember, visual,
  question: { prompt, options, answer, explain },
});

const challenge = (number, title, visual, prompt, options, answer, explain) => ({
  id: `${number}-challenge`, kind: 'challenge', code: `第 ${number} 單元`, title: `${title}總挑戰`,
  goal: '把這一單元學到的方法連起來，讀懂情境、選對方法，再仔細檢查答案。',
  storyBeat: '松果老師把最後一封任務卡交到你手上。這不是比快，而是看看你能不能把學過的方法說清楚。',
  steps: ['先圈出題目中的重要數字與單位。', '用這一單元的方法操作、畫圖或列式。', '把答案放回故事裡檢查一次。'],
  mistake: '只看見數字就急著計算，可能會選錯方法。',
  remember: '慢慢看、清楚想、勇敢試，我能說出自己的理由！',
  visual,
  question: { prompt, options, answer, explain },
});

