const unit = (number, title, icon, color, summary, curriculumSections, image, imageAlt, story, lessons) => ({
  id: `unit-${number}`, number, title, icon, color, summary, curriculumSections, image, imageAlt,
  imageNote: '情境插圖用來帶入故事；精確數量、刻度與答案以互動圖示為準。', story, lessons,
});

